using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
    };

    [Description("Searches the web for information on a given query and returns relevant results. Use this to gather facts, definitions, and current information about a research topic.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up on the web")] string query,
        CancellationToken cancellationToken = default)
    {
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var response = await _httpClient.GetFromJsonAsync<DuckDuckGoResponse>(url, cancellationToken);

            if (response is null)
            {
                return "No results found.";
            }

            var parts = new List<string>();

            if (!string.IsNullOrWhiteSpace(response.Abstract))
            {
                parts.Add($"**Summary**: {response.Abstract} (Source: {response.AbstractSource})");
            }

            if (!string.IsNullOrWhiteSpace(response.Answer))
            {
                parts.Add($"**Answer**: {response.Answer}");
            }

            if (response.RelatedTopics is { Count: > 0 })
            {
                parts.Add("**Related Information**:");
                foreach (var topic in response.RelatedTopics.Take(5))
                {
                    if (!string.IsNullOrWhiteSpace(topic.Text))
                    {
                        parts.Add($"- {topic.Text}");
                    }
                }
            }

            return parts.Count > 0
                ? string.Join("\n", parts)
                : $"No detailed results found for '{query}'. Try rephrasing the query or breaking it into smaller, more specific searches.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    private sealed class DuckDuckGoResponse
    {
        [JsonPropertyName("Abstract")]
        public string? Abstract { get; set; }

        [JsonPropertyName("AbstractSource")]
        public string? AbstractSource { get; set; }

        [JsonPropertyName("Answer")]
        public string? Answer { get; set; }

        [JsonPropertyName("RelatedTopics")]
        public List<RelatedTopic>? RelatedTopics { get; set; }
    }

    private sealed class RelatedTopic
    {
        [JsonPropertyName("Text")]
        public string? Text { get; set; }

        [JsonPropertyName("FirstURL")]
        public string? FirstURL { get; set; }
    }
}

using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed class NoteTool
{
    private readonly List<NoteEntry> _notes = [];

    [Description("Saves a research note with a category label. Use this to record important findings, facts, or insights discovered during research.")]
    public string SaveNote(
        [Description("A short category for the note, e.g. 'definition', 'history', 'key-fact', 'statistic'")] string category,
        [Description("The content of the note to save")] string content)
    {
        _notes.Add(new NoteEntry(category, content));
        return $"Note saved under '{category}'. Total notes: {_notes.Count}.";
    }

    [Description("Retrieves all saved research notes, optionally filtered by category. Use this to review what you have gathered before writing a summary.")]
    public string GetNotes(
        [Description("Optional category filter. Pass empty string to get all notes.")] string category = "")
    {
        var filtered = string.IsNullOrWhiteSpace(category)
            ? _notes
            : _notes.Where(n => n.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return string.IsNullOrWhiteSpace(category)
                ? "No notes saved yet."
                : $"No notes found under category '{category}'.";
        }

        var lines = filtered.Select((n, i) => $"[{i + 1}] ({n.Category}) {n.Content}");
        return $"Found {filtered.Count} note(s):\n{string.Join("\n", lines)}";
    }

    private sealed record NoteEntry(string Category, string Content);
}

