using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using OpenAI;
using ResearchAgent.Tools;

// --- Configuration -----------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build the chat client ---------------------------------------------------
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Register tools ----------------------------------------------------------
var webSearch = new WebSearchTool();
var notes = new NoteTool();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(webSearch.SearchWeb),
    AIFunctionFactory.Create(notes.SaveNote),
    AIFunctionFactory.Create(notes.GetNotes),
};

// --- Create the agent --------------------------------------------------------
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research assistant. Your job is to thoroughly research a topic
        provided by the user by following these steps:

        1. SEARCH: Use the SearchWeb tool multiple times with different queries
           to gather diverse information about the topic. Try broad queries first,
           then drill into specific subtopics.
        2. TAKE NOTES: As you find important facts, save them using the SaveNote
           tool with appropriate categories (e.g., "definition", "history",
           "key-fact", "statistic", "application").
        3. REVIEW: Use GetNotes to review everything you have collected.
        4. SUMMARIZE: Write a well-structured summary of your findings, organized
           by theme. Cite the sources where possible.

        Be thorough — perform at least 3 different searches before summarizing.
        """,
};

// --- Get the research topic --------------------------------------------------
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// --- Run the agent -----------------------------------------------------------
var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
    RetainToolMessages = true,
};

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
    Tools = [.. tools],
};

await foreach (var message in agent.InvokeStreamingAsync(
    history,
    options,
    chatOptions,
    cancellationToken: CancellationToken.None))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Complete ===");

